D.openModal=(title,html,wide=false)=>{if(!$('.modal')?.contains(document.activeElement))D.lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('X')}</button></div>${html}</section></div>`;document.removeEventListener('keydown',trapFocus);document.addEventListener('keydown',trapFocus);clearTimeout(D.modalFocusTimer);D.modalFocusTimer=setTimeout(()=>$('.modal input,.modal textarea,.modal button')?.focus(),20)};
