function filteredMeetings(){return state.meetings.filter(m=>m.status===state.meetingTab&&(!state.query||m.title.toLowerCase().includes(state.query.toLowerCase()))&&(state.scope==='all'||state.scope==='owned'&&m.mine||state.scope==='participating'&&!m.mine)&&(!state.from||m.date&&m.date>=state.from)&&(!state.to||m.date&&m.date<=state.to)).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.time.localeCompare(b.time))}
function meetingResults(){const list=filteredMeetings();if(!list.length)return `<div class="empty-state">${icon('Calendar')}<h3>Встреч не найдено</h3><p>Измените запрос или сбросьте фильтры.</p><button class="btn btn-soft" style="margin-top:15px" data-action="reset-filters">Сбросить фильтры</button></div>`;let prev='!';return list.map(m=>{let head='';if(m.date!==prev){prev=m.date;const day=m.date==='2026-10-13'?'Сегодня':m.date==='2026-10-14'?'Завтра':m.date?'На этой неделе':'Постоянные комнаты';head=`<div class="day-heading">${state.meetingTab==='past'?dateLabel(m.date):day}<span>${m.date&&state.meetingTab!=='past'?dateLabel(m.date):''}</span></div>`}return head+meetingCard(m)}).join('')}
