function canEditMeeting(meeting){return !!meeting?.mine&&meeting.status!=='past';}
function meetingForm(mode,id){
 const m=state.meetings.find(v=>v.id===id),scheduled=mode!=='instant';
 if(mode==='edit'&&!canEditMeeting(m)){D.toast(m?.status==='past'?'Завершённую встречу нельзя редактировать':'Редактирование встречи недоступно');return;}
 const title=m?'Изменить встречу':scheduled?'Запланировать встречу':'Новая встреча';
 const option=(name,label,description,symbol,checked)=>`<label class="meeting-editor-option"><span class="meeting-editor-option-icon" aria-hidden="true">${icon(symbol)}</span><span><strong>${label}</strong><small>${description}</small></span><input type="checkbox" role="switch" name="${name}" aria-label="${label}" ${checked?'checked':''}></label>`;
 D.openModal(title,`<form id="meeting-form" data-mode="${mode}" data-id="${m?.id||''}">
  <div class="meeting-editor-body">
   <div class="meeting-editor-main">
    <label class="field meeting-editor-title">Название встречи<input name="title" required maxlength="100" placeholder="Например, планы на неделю" value="${esc(m?.title||'')}"></label>
    ${scheduled?`<section class="meeting-editor-section" aria-labelledby="meeting-editor-time"><div class="meeting-editor-section-head"><h3 id="meeting-editor-time">${icon('CalendarClock')}Дата и время</h3><span>Москва · UTC+3</span></div><div class="meeting-editor-time-grid"><label class="field">Дата<input type="date" name="date" value="${m?.date||state.scheduleDate||'2026-10-14'}" required></label><label class="field">Начало<input type="time" name="time" value="${m?.time||'11:00'}" required></label><label class="field">Длительность<select name="duration">${[...new Set([15,30,45,60,90,120,m?.duration||30])].sort((a,b)=>a-b).map(v=>`<option value="${v}" ${v===(m?.duration||30)?'selected':''}>${v} минут</option>`).join('')}</select></label></div></section>`:''}
    <label class="field meeting-editor-description"><span class="meeting-editor-label">Повестка встречи <span>Необязательно</span></span><textarea name="description" placeholder="Добавьте темы и вопросы, которые хотите обсудить">${esc(m?.description||'')}</textarea></label>
   </div>
   <aside class="meeting-editor-side" aria-label="Участники и параметры встречи">
    <h3>${icon('Users')}Участники и доступ</h3>
    <label class="field">Пригласить команду<select name="chat"><option value="team">Продуктовая команда · 5 человек</option><option value="dev" ${m?.chat==='dev'?'selected':''}>Разработка · 8 человек</option><option value="design" ${m?.chat==='design'?'selected':''}>Дизайн и исследования · 4 человека</option></select></label>
    ${scheduled?`<label class="field">Кто может присоединиться<select name="access">${['Участники пространства','Все, у кого есть ссылка'].map(v=>`<option ${v===m?.access?'selected':''}>${v}</option>`).join('')}</select></label>`:''}
    <div class="meeting-editor-options">${option('waiting','Зал ожидания','Впускайте гостей во встречу','ShieldCheck',m?.waiting)}${option('record','Автозапись','Сохраните разговор с начала','Video',m?.autoRecord)}</div>
   </aside>
  </div>
  <div class="modal-actions meeting-editor-footer"><span class="meeting-editor-footer-note">${icon('Link')} ${m?'Ссылка на встречу сохранится':scheduled?'Ссылка появится после создания':'Пригласите участников по ссылке'}</span><button class="btn btn-secondary" type="button" data-action="close-modal">Отмена</button><button class="btn btn-primary" type="submit">${icon(m?'Check':scheduled?'CalendarPlus':'ArrowRight')}${m?'Сохранить изменения':scheduled?'Создать встречу':'Начать встречу'}</button></div>
 </form>`,true);
 const modal=$('.modal');modal.classList.add('meeting-editor-modal');
 $('.modal-head',modal).innerHTML=`<span class="meeting-editor-emblem" aria-hidden="true">${icon(scheduled?'CalendarClock':'Video')}</span><div class="meeting-editor-heading"><h2 id="modal-title">${esc(title)}</h2><p>${m?'Все детали встречи — в одном месте.':scheduled?'Выберите время и подготовьте разговор с командой.':'Соберите команду для быстрого разговора.'}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('X')}</button>`;
}
function getMessages(){if(!state.messages[state.chat]){const c=chats.find(c=>c.id===state.chat)||chats[0];state.messages[state.chat]=c.group?[{id:'m1',author:'Анна Кузнецова',initials:'АК',color:'',time:'09:15',text:'Доброе утро, команда! ☀️ Сегодня в 10:00 встречаемся на дизайн-синхронизации.'},{id:'m2',author:'Максим Петров',initials:'МП',color:'peach',time:'09:18',text:'Привет! Подготовил новую сборку. Покажу, что получилось с навигацией.'},{id:'m3',author:state.profile.name,own:true,time:'09:24',text:'Отлично! Добавил вопросы к обсуждению. Посмотрите перед встречей.',file:'Повестка встречи.txt'},{id:'m4',author:'Мария Волкова',initials:'МВ',color:'green',time:'09:31',text:'Я тоже буду. Принесу обратную связь от пользователей — есть несколько интересных наблюдений.',reaction:true},{id:'m5',author:'Анна Кузнецова',initials:'АК',color:'',time:'09:42',text:'Здорово, до встречи на синке! 👋'}]:[{id:'dm1',author:c.name,initials:c.initials,color:c.color,time:'09:15',text:'Привет! Посмотрим обновлённые макеты перед встречей?'},{id:'dm2',own:true,author:state.profile.name,time:'09:20',text:'Да, всё подготовил. Давай обсудим основные изменения.'},{id:'dm3',author:c.name,initials:c.initials,color:c.color,time:'09:28',text:'Отлично, посмотрю макеты!'}]}return state.messages[state.chat]}
function messagesHtml(){if(D.chatMessagesHtml)return D.chatMessagesHtml();return `<div class="message-date">Сегодня, 13 октября</div>${getMessages().map(m=>`<div class="message ${m.own?'own':''}" id="msg-${esc(m.id)}">${m.own?'':avatar(m.initials,m.color)}<div><div class="msg-author">${esc(m.own?'Вы':m.author)}<time>${esc(m.time)} ${m.own?'✓✓':''}</time></div><div class="message-bubble">${m.reply?`<div class="reply-preview">${esc(m.reply)}</div>`:''}${esc(m.text)}${m.file?`<button class="file-pill" data-action="download-attachment" data-id="${esc(m.id)}">${icon('FileText')}<div>${esc(m.file)}<small>Локальное вложение · нажмите, чтобы скачать</small></div>${icon('Download')}</button>`:''}</div>${m.reaction?`<button class="reaction" data-action="react-message" data-id="${m.id}" aria-label="Убрать реакцию">👍 1</button>`:''}<div class="message-actions"><button data-action="reply-message" data-id="${m.id}">Ответить</button><button data-action="react-message" data-id="${m.id}">👍</button>${m.own?`<button data-action="edit-message" data-id="${m.id}">Изменить</button><button data-action="delete-message" data-id="${m.id}">Удалить</button>`:''}</div></div></div>`).join('')}`}
function chatIdentity(c) {
  return `<button class="chat-details-trigger" data-action="chat-info" aria-haspopup="dialog" aria-label="${c.group?'Открыть информацию о группе':'Открыть профиль'} ${esc(c.name)}">${D.chatAvatar(c)}<span><strong>${esc(c.name)}</strong><small class="${c.group?'':'online-text'}">${c.group?`${c.people} участников · 3 в сети`:'В сети'}</small></span>${icon('ChevronDown')}</button>`;
}
D.refreshChatDetails=()=>{
  const c=chats.find(c=>c.id===state.chat);
  if(c&&$('.chat-details-trigger'))$('.chat-details-trigger').outerHTML=chatIdentity(c);
  if($('#chat-results'))$('#chat-results').innerHTML=chatListHtml($('#chat-search')?.value||'');
};
function chatInfoMembers(c) {
  const saved=state.groupSettings?.[c.id];
  const members=saved?saved.members:people.slice(0,Math.max(0,c.people-1)).map((_,i)=>({id:String(i),role:'member'}));
  return [{id:'self',initials:initials(state.profile.name),name:state.profile.name,role:'Владелец',color:'blue',owner:true},...members.flatMap(m=>{const p=people[Number(m.id)];return p?[{id:String(m.id),initials:p[0],name:p[1],role:m.role==='admin'?'Администратор':'Участник',color:p[3],description:p[2]}]:[]})];
}
function chatInfoPane(c,tab) {
  const person=people.find(p=>p[1]===c.name),muted=state.mutedChats?.includes(c.id);
  if(tab==='members')return `<div class="chat-profile-section-title"><div><h3>Участники группы</h3><p>Люди, с которыми вы работаете вместе</p></div><button class="btn btn-secondary btn-small" data-action="ext-group-manage">${icon('UserPlus')}Управлять</button></div><div class="chat-profile-members">${chatInfoMembers(c).map(p=>`<button type="button" class="chat-profile-member" data-action="group-member-info" data-group="${esc(c.id)}" data-member="${esc(p.id)}" aria-haspopup="dialog" aria-label="Открыть профиль ${esc(p.name)}">${p.owner?D.profileAvatar():avatar(p.initials,p.color)}<span class="chat-profile-member-copy"><strong>${esc(p.name)}${p.owner?' (вы)':''}</strong><small>${esc(p.role)}</small></span>${p.owner?'<span class="badge blue">Вы</span>':''}${icon('ChevronRight')}</button>`).join('')}</div>`;
  if(tab==='files') {
    const files=getMessages().filter(m=>m.file);
    return `<div class="chat-profile-section-title"><div><h3>Файлы и материалы</h3><p>Вложения из этой переписки</p></div><span class="badge">${files.length}</span></div>${files.length?`<div class="chat-profile-files">${files.map(m=>`<button class="chat-profile-file" data-action="download-attachment" data-id="${esc(m.id)}"><span class="chat-profile-file-icon">${icon('FileText')}</span><span><strong>${esc(m.file)}</strong><small>${esc(m.own?'Вы':m.author||c.name)} · ${esc(m.time)}</small></span>${icon('Download')}</button>`).join('')}</div>`:`<div class="chat-profile-empty">${icon('FileText')}<h3>Пока нет файлов</h3><p>Здесь появятся файлы, которыми вы поделитесь в чате.</p></div>`}`;
  }
  return `<div class="chat-profile-about"><h3>${c.group?'Описание группы':'О пользователе'}</h3><p>${esc(c.group?(c.description||'Добавьте описание, чтобы участники знали, для чего создана группа.'):(person?.[2]||'Участник рабочего пространства'))}</p></div><dl class="chat-profile-details"><div><dt>${icon('Users')}Рабочее пространство</dt><dd>Продуктовая команда</dd></div>${c.group?`<div><dt>${icon('LockKeyhole')}Тип чата</dt><dd>Групповой чат</dd></div><div><dt>${icon('User')}Владелец группы</dt><dd>${esc(state.profile.name)}</dd></div>`:`<div><dt>${icon('User')}Имя и фамилия</dt><dd>${esc(c.name)}</dd></div><div><dt>${icon('MessageCircle')}Переписка</dt><dd>Личный чат</dd></div>`}</dl><div class="chat-profile-notifications"><span class="chat-profile-setting-icon">${icon('Bell')}</span><div><strong>Уведомления</strong><small>${muted?'Уведомления для этого чата выключены':'Сообщать о новых сообщениях в этом чате'}</small></div><button id="chat-info-notifications" class="chat-profile-switch ${muted?'':'on'}" role="switch" aria-checked="${!muted}" aria-label="Уведомления в этом чате" data-action="mute-chat"><span></span></button></div>`;
}
D.showChatInfo=(tab='about')=>{
  const c=chats.find(c=>c.id===state.chat)||chats[0];
  const tabs=[['about',c.group?'Обзор':'Профиль'],...(c.group?[['members','Участники']]:[]),['files','Файлы']];
  if(!tabs.some(([id])=>id===tab))tab='about';
  D.chatInfoTab=tab;
  const html=`<div id="chat-info-dialog" class="chat-profile-dialog"><div class="chat-profile-hero">${D.chatAvatar(c)}<div class="chat-profile-heading"><h2>${esc(c.name)}</h2><p>${c.group?'Групповой чат · Рабочее пространство':'Участник пространства'}${!c.group?' <span class="chat-profile-status"><i class="dot"></i>В сети</span>':''}</p></div></div><div class="chat-profile-actions"><button class="btn btn-primary" data-action="${c.group?'chat-call':'chat-info-message'}">${icon(c.group?'Video':'MessageCircle')}${c.group?'Начать встречу':'Написать сообщение'}</button><button class="btn btn-secondary" data-action="${c.group?'ext-group-manage':'chat-call'}">${icon(c.group?'Settings':'Phone')}${c.group?'Управление группой':'Позвонить'}</button></div><div class="chat-profile-tabs" role="tablist" aria-label="${c.group?'Информация о группе':'Информация о пользователе'}">${tabs.map(([id,label])=>`<button id="chat-info-tab-${id}" role="tab" tabindex="${id===tab?'0':'-1'}" aria-selected="${id===tab}" aria-controls="chat-info-pane" data-action="chat-info-tab" data-value="${id}">${label}</button>`).join('')}</div><section class="chat-profile-pane" id="chat-info-pane" role="tabpanel" aria-labelledby="chat-info-tab-${tab}" tabindex="0">${chatInfoPane(c,tab)}</section></div>`;
  const existing=$('#chat-info-dialog');
  if(existing){existing.outerHTML=html;$('#modal-title').textContent=c.group?'Информация о группе':'Информация о пользователе';$('#chat-info-tab-'+tab)?.focus();return;}
  if(document.activeElement===document.body||!D.lastFocus?.isConnected)$('.chat-details-trigger')?.focus();
  D.openModal(c.group?'Информация о группе':'Информация о пользователе',html,true);
  $('.modal').classList.add('chat-profile-modal');
};

let memberProfileOrigin=null;
function groupMember(groupId,memberId){const group=chats.find(c=>c.id===groupId&&c.group);return group?{group,member:chatInfoMembers(group).find(p=>p.id===memberId)}:{};}
function showGroupMember(groupId,memberId){
  const {group,member:p}=groupMember(groupId,memberId),dialog=$('#chat-info-dialog');
  if(!p||!dialog)return;
  memberProfileOrigin={groupId,memberId,scroll:$('#chat-info-pane')?.scrollTop||0};
  const attrs=`data-group="${esc(groupId)}" data-member="${esc(memberId)}"`;
  dialog.outerHTML=`<div id="chat-info-dialog" class="chat-profile-dialog"><button type="button" class="member-profile-back" data-action="group-member-back">${icon('ArrowLeft')}К участникам группы</button><div class="chat-profile-hero">${p.owner?D.profileAvatar(true):avatar(p.initials,p.color,true)}<div class="chat-profile-heading"><h2>${esc(p.name)}</h2><p>${p.owner?'Ваш профиль':'Участник пространства'} <span class="chat-profile-status"><i class="dot"></i>В сети</span></p></div></div><div class="chat-profile-actions">${p.owner?`<button class="btn btn-secondary" data-action="navigate" data-value="settings">${icon('Settings')}Настройки профиля</button>`:`<button class="btn btn-primary" data-action="group-member-message" ${attrs}>${icon('MessageCircle')}Написать сообщение</button><button class="btn btn-secondary" data-action="group-member-call" ${attrs}>${icon('Phone')}Позвонить</button>`}</div><section class="chat-profile-pane member-profile-pane" aria-label="Информация о пользователе"><div class="chat-profile-about"><h3>О пользователе</h3><p>${esc(p.description||(p.owner?'Владелец группы':'Участник рабочего пространства'))}</p></div><dl class="chat-profile-details"><div><dt>${icon('User')}Имя и фамилия</dt><dd>${esc(p.name)}</dd></div><div><dt>${icon('Users')}Рабочее пространство</dt><dd>Продуктовая команда</dd></div><div><dt>${icon('MessagesSquare')}Группа</dt><dd>${esc(group.name)}</dd></div><div><dt>${icon('ShieldCheck')}Роль в группе</dt><dd>${esc(p.role)}</dd></div>${p.owner?`<div><dt>${icon('Mail')}Электронная почта</dt><dd>${esc(state.profile.email)}</dd></div>`:''}</dl></section></div>`;
  $('#modal-title').textContent='Информация о пользователе';
  $('.member-profile-back')?.focus();
}
function memberChat(groupId,memberId){
  const {member:p}=groupMember(groupId,memberId);
  if(!p||p.owner)return null;
  let chat=chats.find(c=>!c.group&&c.name===p.name);
  if(!chat){
    chat={id:'person-'+p.id,name:p.name,initials:p.initials,color:p.color,group:false,time:'',unread:0,preview:'Начните переписку',description:p.description};
    chats.push(chat);state.messages[chat.id]=[];
    state.customChats=chats.filter(c=>c.id.startsWith('group-')||c.id.startsWith('person-'));D.save();
  }
  return chat;
}
Object.assign(D.handlers,{
  'group-member-info':b=>showGroupMember(b.dataset.group,b.dataset.member),
  'group-member-back':()=>{
    const origin=memberProfileOrigin;if(!origin||state.chat!==origin.groupId)return;
    D.showChatInfo('members');
    document.querySelectorAll('[data-action="group-member-info"]').forEach(button=>{if(button.dataset.member===origin.memberId)button.focus({preventScroll:true});});
    if($('#chat-info-pane'))$('#chat-info-pane').scrollTop=origin.scroll;
  },
  'group-member-message':b=>{const c=memberChat(b.dataset.group,b.dataset.member);if(c){state.chat=c.id;state.reply='';state.replyTo=null;D.go('chats');$('#message-input')?.focus();}},
  'group-member-call':b=>{const c=memberChat(b.dataset.group,b.dataset.member);if(c)D.startPersonalCall(c.id);}
});

D.chatListPanel=()=>`<aside class="chat-list"><div class="row between"><h1>Чаты</h1>${ib('SquarePen','new-chat','Новый чат')}</div><div class="input-icon">${icon('Search')}<input type="search" id="chat-search" placeholder="Найти чат" aria-label="Найти чат"></div><div class="tabs" role="group" aria-label="Фильтр чатов">${[['all','Все'],['new','Новые'],['direct','Личные'],['group','Группы']].map(([v,t])=>`<button class="${state.chatFilter===v?'active':''}" data-action="chat-filter" data-value="${v}" aria-pressed="${state.chatFilter===v}">${t}</button>`).join('')}</div><div id="chat-results">${chatListHtml()}</div></aside>`;
D.screens.chats=()=>{const c=chats.find(c=>c.id===state.chat)||chats[0];return `${D.chatListPanel()}<section class="chat-main"><header class="chat-header">${chatIdentity(c)}<span class="spacer"></span>${c.group?'':`<button class="btn btn-soft chat-call-icon" data-action="chat-call" aria-label="Позвонить" title="Позвонить">${icon('Phone')}</button>`}${ib('Search','search-chat','Поиск по сообщениям')}<button class="icon-btn chat-header-more" data-action="chat-header-menu" aria-label="Действия с чатом" title="Действия с чатом" aria-haspopup="menu" aria-expanded="false">${icon('MoreHorizontal')}</button></header>${D.chatPinsHtml?.()||''}${D.chatContextHtml?.()||''}<div class="messages" id="messages">${messagesHtml()}</div><form class="chat-composer" id="message-form">${state.reply?`<div class="reply-preview"><span>В ответ: ${esc(state.reply)}</span><span class="spacer"></span>${ib('X','cancel-reply','Отменить ответ')}</div>`:''}<div class="compose-box"><textarea id="message-input" placeholder="Написать сообщение…" aria-label="Написать сообщение" rows="1" maxlength="4000">${esc(state.chatDrafts?.[state.chat]||'')}</textarea><div class="composer-footer">${ib('Paperclip','attach','Прикрепить файл')}${ib('Smile','emoji','Добавить эмодзи')}<input type="file" id="chat-file" hidden><span class="spacer"></span><button class="btn btn-primary" type="submit" aria-label="Отправить сообщение">${icon('Send')}</button></div></div><div class="chat-hint">Enter — отправить · Shift + Enter — новая строка</div></form></section>`};
document.addEventListener('keydown',e=>{if(!e.target.matches('.chat-profile-tabs [role=tab]'))return;if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('.chat-profile-tabs [role=tab]')],index=tabs.indexOf(e.target);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;D.showChatInfo(tabs[next].dataset.value)});
function chatListHtml(query=''){return chats.filter(c=>(!D.chatIsVisible||D.chatIsVisible(c.id))&&(!query||c.name.toLowerCase().includes(query.toLowerCase()))&&(state.chatFilter==='all'||state.chatFilter==='new'&&c.unread>0||state.chatFilter==='group'&&c.group||state.chatFilter==='direct'&&!c.group)).map(c=>`<button class="chat-item ${state.chat===c.id?'active':''}" data-action="open-chat" data-id="${c.id}">${D.chatAvatar(c)}<div><strong>${esc(c.name)}</strong><p>${esc(state.messages[c.id]?(state.messages[c.id].at(-1)?.text||'Начните переписку'):c.preview)}</p></div><div><time>${state.messages[c.id]?.length===0?'':c.time}</time>${c.unread?`<span class="nav-count">${c.unread}</span>`:''}</div></button>`).join('')||`<div class="empty-state"><p>${state.chatFilter==='new'&&!query.trim()?'Нет новых сообщений':'Чат не найден'}</p></div>`}
D.screens.calendar=()=>{const year=state.calendarYear,month=state.calendarMonth,first=(new Date(year,month,1).getDay()+6)%7;const count=Math.ceil((first+new Date(year,month+1,0).getDate())/7)*7;let cells='';for(let i=0;i<count;i++){const dt=new Date(year,month,i-first+1),date=`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;const events=state.meetings.filter(m=>m.date===date);cells+=`<div class="month-cell ${dt.getMonth()!==month?'outside':''} ${date==='2026-10-13'?'today':''}" data-action="calendar-add" data-value="${date}"><button class="day-number" aria-label="Создать встречу ${dateLabel(date)}">${dt.getDate()}</button>${events.map(m=>`<button class="calendar-event ${m.status==='active'?'green':''}" data-action="calendar-info" data-id="${esc(m.id)}" aria-haspopup="dialog"><strong>${m.time}</strong> ${esc(m.title)}</button>`).join('')}</div>`}return `${heading('Календарь','Время для важных разговоров.',`<button class="btn btn-primary" data-action="schedule">${icon('Plus')}Запланировать встречу</button>`)}<div class="section-heading"><div class="month-controls"><h2>${months[month]} ${year}</h2>${ib('ChevronLeft','month-prev','Предыдущий месяц')}${ib('ChevronRight','month-next','Следующий месяц')}<button class="btn btn-secondary btn-small" data-action="today">Сегодня</button></div><span class="muted" style="font-size:10px">Москва · UTC+3</span></div><div class="month-board">${['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'].map(d=>`<div class="month-weekday">${d}</div>`).join('')}${cells}</div><div class="calendar-legend"><span><i class="dot" style="color:var(--accent)"></i> Запланированные встречи</span><span><i class="dot" style="color:var(--green)"></i> Активная встреча</span><span>Нажмите на день, чтобы создать встречу</span></div>`};
function showMeetingInformation(id){
  const meeting=state.meetings.find(item=>item.id===id);
  if(!meeting){D.toast('Встреча больше недоступна');return;}
  const active=meeting.status==='active',past=meeting.status==='past';
  const status=active?'Идёт сейчас':past?'Завершена':'Запланирована';
  const date=meeting.date?new Date(meeting.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}):'Постоянная комната';
  const owner=meeting.mine||meeting.owner==='Вы'?`${state.profile.name} (вы)`:meeting.owner;
  const fact=(symbol,label,value)=>`<div><span class="meeting-fact-icon" aria-hidden="true">${icon(symbol)}</span><div><dt>${label}</dt><dd>${value}</dd></div></div>`;
  D.openModal(meeting.title,`<div id="calendar-meeting-info" class="calendar-meeting-info">
    <div class="calendar-meeting-content">
      <dl class="calendar-meeting-facts">
        ${fact('CalendarDays','Дата и время',`${esc(date)}<small>${meeting.time?`<b>${esc(meeting.time)}</b><span> · </span>`:''}Москва · UTC+3</small>`)}
        ${fact('Clock','Длительность',meeting.duration?`${esc(meeting.duration)} <span class="meeting-fact-unit">мин</span>`:'Без ограничения')}
        ${fact('User','Организатор',esc(owner||'Не указан'))}
        ${fact('Users','Участники',`${esc(meeting.people||0)} <span class="meeting-fact-unit">в списке встречи</span>`)}
      </dl>
      <section class="calendar-meeting-description"><h3>О встрече</h3><p class="${meeting.description?'':'is-empty'}">${esc(meeting.description||'Описание пока не добавлено.')}</p></section>
      <div class="calendar-meeting-secondary">${past?'':`<button class="btn btn-secondary" data-action="copy-meeting" data-id="${esc(meeting.id)}">${icon('Link')}Скопировать ссылку</button>`}<button class="btn btn-secondary" data-action="meeting-chat" data-id="${esc(meeting.id)}">${icon('MessageCircle')}Чат встречи</button></div>
    </div>
    <footer class="calendar-meeting-footer">
      ${meeting.mine?`<div class="calendar-meeting-owner-actions">${canEditMeeting(meeting)?`<button class="btn meeting-edit-action" data-action="edit-meeting" data-id="${esc(meeting.id)}" aria-label="Изменить встречу" title="Изменить встречу">${icon('Pencil')}<span>Изменить</span></button>`:''}<button class="icon-btn meeting-delete-action" data-action="delete-meeting" data-id="${esc(meeting.id)}" aria-label="Удалить встречу" title="Удалить встречу">${icon('Trash2')}</button></div>`:''}
      <div class="modal-actions"><button class="btn btn-secondary" data-action="close-modal">Закрыть</button><button class="btn btn-primary" data-action="${past?'navigate':'join-meeting'}" data-value="recordings" data-id="${esc(meeting.id)}">${icon(past?'CirclePlay':'Video')}${past?'Записи встреч':'Подключиться'}</button></div>
    </footer>
  </div>`);
  const modal=$('.modal');modal.classList.add('calendar-meeting-modal');modal.dataset.meetingStatus=meeting.status;
  $('.modal-head',modal).innerHTML=`<span class="meeting-info-emblem" aria-hidden="true">${icon(active?'Video':past?'Check':'CalendarClock')}</span><div class="meeting-info-heading"><span class="meeting-info-status ${active?'is-active':past?'is-past':''}">${active?'<i class="dot"></i>':icon(past?'Check':'CalendarDays')}${status}</span><h2 id="modal-title">${esc(meeting.title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('X')}</button>`;
}
function openMeetingInformation(id){
  const meeting=state.meetings.find(item=>item.id===id);
  if(!meeting){D.toast('Встреча больше недоступна');return;}
  state.selected=null;state.meetingTab=meeting.status;state.query='';state.from='';state.to='';state.scope='all';
  D.go('meetings');
  const trigger=[...document.querySelectorAll('.meeting-card-actions [data-action="select-meeting"]')].find(button=>button.dataset.id===id);
  trigger?.focus({preventScroll:true});
  showMeetingInformation(id);
}
function recordCards(query=''){return records.map((r,i)=>({r,i})).filter(({r})=>r.title.toLowerCase().includes(query.toLowerCase())).map(({r,i})=>`<article class="record-card"><button class="record-thumbnail variant-${i%3}" style="width:100%" data-action="record" data-id="${i}" aria-label="Открыть запись ${esc(r.title)}"><div class="record-mini-grid">${people.map(p=>`<div>${avatar(p[0],p[3])}</div>`).join('')}</div><span class="play-overlay">${icon('Play')}</span><span class="duration-badge">${r.duration}</span></button><div class="record-content"><h3>${esc(r.title)}</h3><p>${r.date} 2026 · ${r.people} участников</p><div class="row record-actions">${ib('ArrowUpRight','record','Открыть запись',`data-id="${i}"`)}</div></div></article>`).join('')||'<div class="empty-state">Записи не найдены</div>'}
D.screens.recordings=()=>`${heading('Записи встреч','',`<span class="badge">${records.length} записей · Демо-данные</span>`)}<div class="records-toolbar"><div class="input-icon">${icon('Search')}<input id="record-search" type="search" placeholder="Найти запись" aria-label="Найти запись"></div><div class="records-view-switch" role="group" aria-label="Вид записей">${[['list','List','Список'],['grid','Grid2X2','Плитка']].map(([view,glyph,label])=>`<button type="button" data-action="record-view" data-value="${view}" aria-pressed="${state.recordView===view}">${icon(glyph)}<span>${label}</span></button>`).join('')}</div></div><div class="record-grid ${state.recordView==='list'?'records-list':''}" id="record-grid">${recordCards()}</div>`;
D.handlers['record-view']=b=>{
  const view=b.dataset.value;if(!['list','grid'].includes(view))return;
  state.recordView=view;D.save();
  $('#record-grid')?.classList.toggle('records-list',view==='list');
  document.querySelectorAll('[data-action="record-view"]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.value===view)));
};
const transcript=[['00:00','Анна Кузнецова','Давайте начнём. Сегодня обсудим новое направление продукта и ключевые сценарии пользователей.'],['02:34','Александр Соколов','Наша цель — сделать совместную работу понятнее. Главный фокус — встречи, чаты и быстрый доступ к материалам.'],['06:12','Мария Волкова','На интервью пользователи чаще всего отмечали, что хотят видеть все материалы встречи в одном месте.'],['12:45','Максим Петров','Технически мы можем объединить записи и сообщения в контекст встречи. Предлагаю начать с навигации.'],['24:18','Анна Кузнецова','Договорились: подготовим макет десктопной версии, затем проверим его на основных сценариях.'],['38:06','Александр Соколов','Итак, зафиксируем задачи и вернёмся к ним на следующей синхронизации. Спасибо всем!']];
function transcriptHtml(query=''){if(state.recordTab==='summary')return `<h3 style="margin:20px 0 12px">Главное за 2 минуты</h3><p class="muted" style="font-size:11px;line-height:1.9">Команда обсудила развитие MeetSpace. Решили объединить встречи, переписку и материалы в одном рабочем пространстве. Десктопный интерфейс получит постоянную навигацию и панели деталей.</p><div class="divider"></div><h3 style="margin-bottom:12px">Принятые решения</h3><p class="muted" style="font-size:11px;line-height:2">1. Начать с навигации и основных сценариев.<br>2. Подготовить интерактивный макет Windows.<br>3. Проверить макет с командой на следующей встрече.</p>`;if(state.recordTab==='tasks')return ['Подготовить десктопный макет — Анна','Проверить сценарии работы — Мария','Оценить реализацию навигации — Максим'].map((t,i)=>`<label class="task-check"><input type="checkbox" data-task="${i}" ${state.recordTasks?.[i]?'checked':''}>${t}</label>`).join('');return transcript.filter(t=>t.join(' ').toLowerCase().includes(query.toLowerCase())).map(t=>`<button class="transcript-line" style="width:100%;text-align:left" data-action="seek-record" data-value="${t[0]}"><time>${t[0]}</time><div><strong>${t[1]}</strong><p>${t[2]}</p></div></button>`).join('')||'<p class="muted">Совпадений не найдено</p>'}
D.screens.recording=()=>{const r=records[state.record]||records[0];return `${heading(esc(r.title),`${r.date} 2026 · ${r.people} участников · ${r.duration}`,`<button class="btn btn-secondary" data-action="navigate" data-value="recordings">${icon('ArrowLeft')}Все записи</button>`)}<div class="record-detail"><div><div class="record-player"><div class="row between"><span>${icon('Video')} ${esc(r.title)}</span><span class="badge">Демо записи</span></div><div class="record-mini-grid">${people.map(p=>`<div>${avatar(p[0],p[3])}</div>`).join('')}</div><div class="player-controls"><button data-action="play-record" aria-label="Воспроизвести демо записи" id="play-button">${icon('Play')}</button><time id="record-time">00:00</time><input type="range" id="record-progress" aria-label="Позиция записи" min="0" max="${parseInt(r.duration)*60+parseInt(r.duration.split(':')[1])}" value="0"><time>${r.duration}</time>${ib('Volume2','record-audio','Информация о звуке')}</div></div><div class="record-notes panel"><h3>О записи</h3><p>Демонстрация интерфейса проигрывателя. Вместо видео показаны участники; таймлайн связан с расшифровкой. В подключённом приложении здесь будет запись встречи.</p><div class="row" style="margin-top:18px"><button class="btn btn-secondary btn-small" data-action="download-transcript">${icon('Download')}Расшифровка .txt</button><button class="btn btn-secondary btn-small" data-action="copy-record">${icon('Link')}Скопировать ссылку</button></div></div></div><section class="transcript panel"><div class="tabs">${[['transcript','Расшифровка'],['summary','Итоги'],['tasks','Задачи']].map(([id,t])=>`<button class="${state.recordTab===id?'active':''}" data-action="record-tab" data-value="${id}">${t}</button>`).join('')}</div>${state.recordTab==='transcript'?`<div class="input-icon">${icon('Search')}<input id="transcript-search" type="search" placeholder="Поиск по расшифровке" aria-label="Поиск по расшифровке"></div>`:''}<div id="transcript-content">${transcriptHtml()}</div></section></div>`};
D.download=(filename,text,type='text/plain;charset=utf-8')=>{const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
D.localLink=(screen,values={})=>{const u=new URL(location.href);u.search='';u.searchParams.set('screen',screen);for(const [k,v]of Object.entries(values))u.searchParams.set(k,v);return u.href};
