function prepareCall(m,personal=false,screen='prejoin'){if(!personal&&state.personalCall?.active)state.personalCall.active=false;state.call={title:m.title,personal,mic:true,camera:false,sharing:false,presenting:!personal,presentationHidden:false,recording:!!m.autoRecord,hand:false,panel:null,meetingId:m.id,startedAt:screen==='call'?Date.now():undefined};D.go(screen)}
